<template>
  <div class="stack" style="--gap:16px" v-if="spec" :key="res">
    <div class="row between wrap"><div class="stack" style="--gap:2px"><h2 class="h2">{{ spec.title }}</h2><p class="small muted" style="max-width:70ch">{{ spec.note }}</p></div>
      <button v-if="spec.fields && spec.create !== false" class="btn btn-primary" @click="edit()"><ep-ico name="plus" :size="18" /> {{ spec.add || 'Nuevo' }}</button></div>
    <ep-table ref="t" :resource="spec.resource || res" :columns="spec.cols" :filters="spec.filters || []" :clickable="!!spec.fields" @row-click="edit" :export-name="res" :search-placeholder="spec.search || 'Buscar…'">
      <template #cell-active="{ row }"><ep-badge :status="row.active ? 'active' : 'dismissed'" :text="row.active ? 'Activo' : 'Inactivo'" /></template>
      <template #cell-role="{ row }"><span class="chip">{{ row.role }}</span></template>
      <template #cell-status="{ row }"><ep-badge :status="row.status" /></template>
    </ep-table>
    <ep-modal :open="open" :title="form.id ? 'Editar' : (spec.add || 'Nuevo')" wide @close="open = false"><ep-form v-if="spec.fields" :fields="spec.fields" v-model="form" :busy="busy" @submit="save" /></ep-modal>
    <ep-modal :open="!!secret" title="Guárdalo ahora" @close="secret = null"><div v-if="secret" class="stack"><p class="small muted">{{ secret.note }}</p><div class="card card-pad row between"><b class="tag-mono" style="word-break:break-all">{{ secret.value }}</b><button class="btn btn-ghost btn-sm" @click="EP.copy(secret.value)">Copiar</button></div></div><template #footer><button class="btn btn-primary" @click="secret = null">Listo</button></template></ep-modal>
  </div>
  <ep-empty v-else icon="🧭" title="Sección no disponible">Elige una opción del menú.</ep-empty>
</template>
<script>
const T = (key, label, o) => ({ key, label, ...o });
const SPECS = {
  points: { title: 'Puntos', note: 'Los negocios afiliados. La comisión % o fija se aplica al recolectar el efectivo de excursiones; guías y servicios traen la suya.', add: 'Nuevo punto', cols: [{ key: 'name', label: 'Punto' }, { key: 'address', label: 'Dirección' }, { key: 'whatsapp', label: 'WhatsApp' }, { key: 'commission_rate', label: 'Comisión %', fmt: 'num', align: 'right' }, { key: 'tier', label: 'Nivel' }, { key: 'active', label: 'Estado' }],
    fields: [T('name', 'Nombre', { required: true }), T('whatsapp', 'WhatsApp', { type: 'tel' }), T('address', 'Dirección', { wide: true }), T('lat', 'Latitud', { type: 'number', step: 'any' }), T('lng', 'Longitud', { type: 'number', step: 'any' }), T('hours', 'Horario'), T('maps_url', 'Enlace de mapa'), T('commission_type', 'Tipo de comisión', { type: 'select', options: ['percent', 'fixed'], required: true }), T('commission_rate', 'Comisión % (si es porcentaje)', { type: 'number', step: 'any' }), T('commission_amount', 'Comisión fija (MXN)', { type: 'number' }), T('tier', 'Nivel', { type: 'select', options: ['basic', 'pro', 'hub'] }), T('active', 'Activo', { type: 'checkbox' })] },
  providers: { title: 'Proveedores', note: 'Quienes operan las excursiones. El fee de Easypoint y los datos de pago se usan al liquidar cada salida.', add: 'Nuevo proveedor', cols: [{ key: 'name', label: 'Proveedor' }, { key: 'email', label: 'Correo' }, { key: 'fee_type', label: 'Fee' }, { key: 'fee_rate', label: '% / fijo', fmt: 'num', align: 'right' }, { key: 'bank_name', label: 'Banco' }, { key: 'active', label: 'Estado' }],
    fields: [T('name', 'Nombre', { required: true }), T('whatsapp', 'WhatsApp', { type: 'tel' }), T('email', 'Correo', { type: 'email' }), T('payout_days', 'Días para pagarle', { type: 'number' }), T('fee_type', 'Tipo de fee', { type: 'select', options: ['percent', 'fixed'], required: true }), T('fee_rate', 'Fee % sobre ventas', { type: 'number', step: 'any' }), T('fee_amount', 'Fee fijo por reserva', { type: 'number' }), T('beneficiary', 'Beneficiario'), T('clabe', 'CLABE'), T('bank_name', 'Banco'), T('active', 'Activo', { type: 'checkbox' })] },
  excursions: { title: 'Excursiones (todas)', note: 'Catálogo completo. Los proveedores editan las suyas desde su panel.', create: false, cols: [{ key: 'name', label: 'Excursión' }, { key: 'destination', label: 'Destino' }, { key: 'price', label: 'Precio', fmt: 'money', align: 'right' }, { key: 'provider_id', label: 'Prov.' }, { key: 'active', label: 'Estado' }] },
  departures: { title: 'Fechas de salida', note: 'Cada fila es una salida con su cupo y estado.', add: 'Nueva fecha', cols: [{ key: 'excursion_id', label: 'Excursión #' }, { key: 'date', label: 'Fecha', fmt: 'date' }, { key: 'capacity', label: 'Cupo', fmt: 'num', align: 'right' }, { key: 'status', label: 'Estado' }, { key: 'note', label: 'Nota' }],
    fields: [T('excursion_id', 'ID de excursión', { type: 'number', required: true }), T('date', 'Fecha', { type: 'date', required: true }), T('capacity', 'Cupo (0 = el de la excursión)', { type: 'number' }), T('status', 'Estado', { type: 'select', options: ['open', 'closed', 'cancelled', 'completed'] }), T('note', 'Nota', { wide: true })] },
  services: { title: 'Servicios', note: 'Catálogo de servicios que los puntos pueden vender, con su comisión.', add: 'Nuevo servicio', search: 'Nombre o categoría…', cols: [{ key: 'name', label: 'Servicio' }, { key: 'category', label: 'Categoría' }, { key: 'commission_rate', label: 'Comisión %', fmt: 'num', align: 'right' }, { key: 'commission_amount', label: 'Fija', fmt: 'money', align: 'right' }, { key: 'active', label: 'Estado' }],
    fields: [T('name', 'Nombre', { required: true, wide: true }), T('category', 'Categoría', { type: 'select', required: true, options: ['pagos', 'recargas', 'seguros', 'boletos', 'impresion', 'sim', 'devoluciones', 'remesas', 'certificados', 'publicidad', 'marketplace', 'farmacia', 'locker', 'reciclaje', 'productos_locales', 'b2b', 'otros'] }), T('unit', 'Unidad', { placeholder: 'por cobro' }), T('commission_type', 'Tipo de comisión', { type: 'select', options: ['percent', 'fixed'] }), T('commission_rate', 'Comisión %', { type: 'number', step: 'any' }), T('commission_amount', 'Comisión fija', { type: 'number' }), T('description', 'Descripción', { type: 'textarea' }), T('icon', 'Ícono'), T('active', 'Activo', { type: 'checkbox' })] },
  pricing_rules: { title: 'Precios y promociones', note: 'Reglas de precio dinámico (requieren activar «pricing.dynamic_enabled» en Automatización) y códigos promocionales (siempre activos). El descuento total se topa en pricing.max_discount_pct.', add: 'Nueva regla', cols: [{ key: 'label', label: 'Regla' }, { key: 'kind', label: 'Tipo' }, { key: 'pct', label: '%', fmt: 'num', align: 'right' }, { key: 'amount', label: 'Monto', fmt: 'money', align: 'right' }, { key: 'code', label: 'Código' }, { key: 'uses', label: 'Usos', fmt: 'num', align: 'right' }, { key: 'active', label: 'Estado' }],
    fields: [T('label', 'Nombre', { required: true, wide: true }), T('kind', 'Tipo', { type: 'select', required: true, options: [{ value: 'early_bird', label: 'Compra anticipada' }, { value: 'last_minute', label: 'Última hora' }, { value: 'group', label: 'Grupo' }, { value: 'surge', label: 'Alta demanda (+)' }, { value: 'member', label: 'Socio Club' }, { value: 'promo_code', label: 'Código promocional' }] }), T('excursion_id', 'Sólo para excursión # (0 = todas)', { type: 'number' }), T('pct', '% de ajuste', { type: 'number', step: 'any' }), T('amount', 'Monto fijo (promo)', { type: 'number' }), T('days', 'Días (anticipada: mínimo · última hora: máximo)', { type: 'number' }), T('min_people', 'Mínimo de personas (grupo)', { type: 'number' }), T('fill_pct', '% de llenado (umbral)', { type: 'number' }), T('code', 'Código (promo)'), T('max_uses', 'Usos máximos (0 = ilimitado)', { type: 'number' }), T('valid_from', 'Vigente desde', { type: 'date' }), T('valid_to', 'Vigente hasta', { type: 'date' }), T('active', 'Activa', { type: 'checkbox' })] },
  users: { title: 'Usuarios', note: 'Cuentas del equipo, puntos, choferes y proveedores. Al crear una, se genera una contraseña temporal.', add: 'Nuevo usuario', create: 'user', search: 'Nombre o correo…', cols: [{ key: 'name', label: 'Nombre' }, { key: 'email', label: 'Correo' }, { key: 'role', label: 'Rol' }, { key: 'point_id', label: 'Punto #' }, { key: 'provider_id', label: 'Prov. #' }, { key: 'last_login_at', label: 'Último acceso', fmt: 'ago' }, { key: 'active', label: 'Estado' }],
    fields: [T('name', 'Nombre', { required: true }), T('email', 'Correo', { type: 'email', required: true }), T('role', 'Rol', { type: 'select', required: true, options: [{ value: 'admin', label: 'Administrador' }, { value: 'support', label: 'Soporte' }, { value: 'sales', label: 'Ventas' }, { value: 'operator', label: 'Punto' }, { value: 'driver', label: 'Chofer' }, { value: 'provider', label: 'Proveedor' }] }), T('phone', 'Teléfono', { type: 'tel' }), T('point_id', 'Punto # (rol Punto)', { type: 'number' }), T('provider_id', 'Proveedor # (rol Proveedor)', { type: 'number' }), T('active', 'Activo', { type: 'checkbox' })] },
  partners: { title: 'Socios e-commerce (API)', note: 'Tiendas que envían paquetes a puntos con una llave de API. La llave se muestra una sola vez al crearla.', add: 'Nuevo socio', create: 'partner', cols: [{ key: 'name', label: 'Socio' }, { key: 'key_prefix', label: 'Prefijo' }, { key: 'parcels', label: 'Paquetes', fmt: 'num', align: 'right' }, { key: 'fee_per_parcel', label: 'Fee/paquete', fmt: 'money', align: 'right' }, { key: 'active', label: 'Estado' }],
    fields: [T('name', 'Nombre de la tienda', { required: true }), T('contact_email', 'Correo de contacto', { type: 'email' }), T('fee_per_parcel', 'Fee por paquete (MXN)', { type: 'number' }), T('webhook_url', 'Webhook (opcional)', { wide: true })] },
  wallets: { title: 'Monederos de crédito', note: 'Pasivo con clientes: crédito vigente que se aplica solo a su siguiente reserva.', create: false, cols: [{ key: 'customer_name', label: 'Cliente' }, { key: 'customer_phone', label: 'Teléfono' }, { key: 'balance', label: 'Saldo', fmt: 'money2', align: 'right' }, { key: 'updated_at', label: 'Actualizado', fmt: 'ago' }] },
  events: { title: 'Eventos', note: 'Línea de tiempo auditable de reservas, salidas, paquetes y tickets.', create: false, cols: [{ key: 'created_at', label: 'Fecha', fmt: 'dt' }, { key: 'entity', label: 'Entidad' }, { key: 'entity_id', label: '#' }, { key: 'from_state', label: 'De' }, { key: 'to_state', label: 'A' }, { key: 'actor', label: 'Actor' }, { key: 'note', label: 'Nota' }] },
  audit: { title: 'Auditoría', note: 'Quién cambió qué en el sistema.', create: false, cols: [{ key: 'created_at', label: 'Fecha', fmt: 'dt' }, { key: 'actor', label: 'Actor' }, { key: 'action', label: 'Acción' }, { key: 'target', label: 'Objeto' }, { key: 'target_id', label: '#' }, { key: 'detail', label: 'Detalle' }] },
  jobs: { title: 'Tareas diferidas', note: 'Cola del motor: reintentos con espera creciente.', create: false, cols: [{ key: 'created_at', label: 'Creada', fmt: 'ago' }, { key: 'kind', label: 'Tipo' }, { key: 'run_at', label: 'Corre', fmt: 'dt' }, { key: 'status', label: 'Estado' }, { key: 'attempts', label: 'Intentos', fmt: 'num' }, { key: 'last_error', label: 'Error' }] }
};
export default {
  data() { return { EP, open: false, busy: false, form: {}, secret: null }; },
  computed: { res() { return EP.view.params.res; }, spec() { return SPECS[this.res]; } },
  methods: {
    edit(r) { if (!this.spec.fields) return; this.form = r && r.id ? { ...r } : { active: true }; this.open = true; },
    async save(f) {
      this.busy = true;
      try {
        const body = { ...f }; Object.keys(body).forEach((k) => { if (typeof body[k] === 'boolean') body[k] = body[k] ? 1 : 0; });
        const res = this.spec.resource || this.res;
        if (!f.id && this.spec.create === 'user') { const r = await EP.post('/admin/users', body); this.secret = { value: r.temp_password, note: 'Contraseña temporal del usuario nuevo. Pídele que la cambie al entrar.' }; }
        else if (!f.id && this.spec.create === 'partner') { const r = await EP.post('/admin/partners', body); this.secret = { value: r.api_key, note: r.note }; }
        else if (f.id) await EP.put('/r/' + res + '/' + f.id, body);
        else await EP.post('/r/' + res, body);
        EP.toast('Guardado', 'ok'); this.open = false; this.$refs.t.reload();
      } catch (e) { EP.err(e); } finally { this.busy = false; }
    }
  }
};
</script>
